// NewIndexLock creates a lock for the given index directory and collection.
// For SQLite: lockPath is derived from the index file path (sibling .lock file).
// For Qdrant: lockPath is derived from data dir + collection name.
func NewIndexLock(indexPath, storageType, collectionName string) *IndexLock {
	var lockPath string
	if storageType == "qdrant" {
		// For Qdrant, use a per-collection lock in a temp-safe location
		lockDir := os.TempDir()
		lockPath = filepath.Join(lockDir, fmt.Sprintf(".semantic-%s.lock", collectionName))
	} else {
		// For SQLite, lock file sits next to the index DB
		lockPath = indexPath + ".lock"
	}

	return &IndexLock{
		flock: flock.New(lockPath),
		path:  lockPath,
	}
}

// IndexLock provides cross-process file locking for index operations.
// Prevents concurrent index/index-update processes from corrupting shared state.
type IndexLock struct {
	flock *flock.Flock
	path  string
}

// TryLock attempts to acquire an exclusive lock without blocking.
// Returns true if lock was acquired, false if another process holds it.
// Use for index-update operations that should silently skip if busy.
func (l *IndexLock) TryLock() (bool, error) {
	return l.flock.TryLock()
}

// fileHashID generates a unique ID for file hash storage
func fileHashID(filePath string) string {
	return stringToUUID("file_hash:" + filePath)
}

func TestIndexLock_TryLock(t *testing.T) {
	tmpDir := t.TempDir()
	indexPath := filepath.Join(tmpDir, "semantic.db")

	lock := NewIndexLock(indexPath, "sqlite", "")
	locked, err := lock.TryLock()
	if err != nil {
		t.Fatalf("TryLock failed: %v", err)
	}
	if !locked {
		t.Fatal("expected TryLock to succeed on fresh lock")
	}
	defer lock.Unlock()
}

func TestIndexLock_ReusableAfterUnlock(t *testing.T) {
	tmpDir := t.TempDir()
	indexPath := filepath.Join(tmpDir, "semantic.db")

	lock := NewIndexLock(indexPath, "sqlite", "")

	// Lock, unlock, lock again
	if err := lock.Lock(5 * time.Second); err != nil {
		t.Fatalf("first Lock failed: %v", err)
	}
	if err := lock.Unlock(); err != nil {
		t.Fatalf("Unlock failed: %v", err)
	}

	locked, err := lock.TryLock()
	if err != nil {
		t.Fatalf("second TryLock failed: %v", err)
	}
	if !locked {
		t.Fatal("expected TryLock to succeed after unlock")
	}
	lock.Unlock()
}

// Lock acquires an exclusive lock, blocking up to timeout.
// Use for full index rebuilds that must wait for other operations to finish.
func (l *IndexLock) Lock(timeout time.Duration) error {
	ctx, cancel := context.WithTimeout(context.Background(), timeout)
	defer cancel()

	locked, err := l.flock.TryLockContext(ctx, 500*time.Millisecond)
	if err != nil {
		return fmt.Errorf("failed to acquire index lock %s: %w", l.path, err)
	}
	if !locked {
		return fmt.Errorf("timed out waiting for index lock %s after %v", l.path, timeout)
	}
	return nil
}

func TestIndexLock_LockUnlock(t *testing.T) {
	tmpDir := t.TempDir()
	indexPath := filepath.Join(tmpDir, "semantic.db")

	lock := NewIndexLock(indexPath, "sqlite", "")
	if err := lock.Lock(5 * time.Second); err != nil {
		t.Fatalf("failed to acquire lock: %v", err)
	}
	if err := lock.Unlock(); err != nil {
		t.Fatalf("failed to release lock: %v", err)
	}
}

// Unlock releases the lock.
func (l *IndexLock) Unlock() error {
	return l.flock.Unlock()
}

func TestIndexLock_TryLock_Contention(t *testing.T) {
	tmpDir := t.TempDir()
	indexPath := filepath.Join(tmpDir, "semantic.db")

	// First lock holder
	lock1 := NewIndexLock(indexPath, "sqlite", "")
	locked, err := lock1.TryLock()
	if err != nil {
		t.Fatalf("lock1 TryLock failed: %v", err)
	}
	if !locked {
		t.Fatal("expected lock1 TryLock to succeed")
	}
	defer lock1.Unlock()

	// Second attempt should fail (non-blocking)
	lock2 := NewIndexLock(indexPath, "sqlite", "")
	locked2, err := lock2.TryLock()
	if err != nil {
		t.Fatalf("lock2 TryLock failed: %v", err)
	}
	if locked2 {
		t.Fatal("expected lock2 TryLock to fail due to contention")
		lock2.Unlock()
	}
}
